# aplicar
for fn in glob.glob(f"{ENG}/*.json"):
    base = os.path.basename(fn)
    e = load(fn)
    sp = os.path.join(ESP, base)
    out = load(sp) if os.path.exists(sp) else dict(e)
    for k, v in e.items():
        if not isinstance(v, str): out[k]=v; continue
        if k in {**T,**KW,**CHAR,**ANC,**REL,**UI,**POW,**CARDS}:
            out[k] = {**T,**KW,**CHAR,**ANC,**REL,**UI,**POW,**CARDS}[k]
        elif v in RULES:
            out[k] = RULES[v]
        # si no, queda lo que tenga el scaffold (oficial o ingles)
    json.dump(out, open(sp,"w",encoding="utf-8"), ensure_ascii=False, indent=2)
print("Acheron traducido")
